from qiskit import QuantumCircuit
from qiskit.quantum_info import DensityMatrix, Pauli, Statevector, partial_trace

# The five states MUST mirror data/figures/s2-q042/generate.py — the rendered
# figures are plot_bloch_multivector drawings of exactly these states.


def state(*gates):
    qc = QuantumCircuit(2)
    for name, *args in gates:
        getattr(qc, name)(*args)
    return Statevector(qc)


def stem_state():
    return state(("h", 0), ("s", 0), ("x", 1))


VARIANTS = {
    "A": state(("h", 0), ("x", 1)),
    "B": state(("h", 0), ("s", 0)),
    "C": state(("h", 1), ("s", 1), ("x", 0)),
    "D": stem_state(),
    "E": partial_trace(stem_state(), [1]),
}


def spheres(st):
    """One Bloch vector per sphere the drawer puts on the figure."""
    rho = DensityMatrix(st)
    n = len(rho.dims())
    out = []
    for i in range(n):
        red = partial_trace(rho, [j for j in range(n) if j != i])
        out.append(tuple(
            round(float(red.expectation_value(Pauli(p)).real), 3) for p in "XYZ"
        ))
    return tuple(out)


target = spheres(stem_state())
proven, evidence, observed = [], {}, {}
for key, st in sorted(VARIANTS.items()):
    s = spheres(st)
    match = s == target
    observed[key] = [list(v) for v in s]
    evidence[key] = (
        f"figure draws {len(s)} sphere(s) with Bloch vectors (x, y, z) {list(s)}"
        f" vs the stem's {list(target)} -> match={match}"
    )
    if match:
        proven.append(key)

observed["stem"] = [list(v) for v in target]
emit_verdict({"answer": proven, "evidence": evidence, "observed": observed})
